import { DatabaseSync } from 'node:sqlite';

const SORT_SQL = {
  newest: 'b.created_at DESC, b.id DESC',
  oldest: 'b.created_at ASC, b.id ASC',
  az: 'b.title COLLATE NOCASE ASC, b.id ASC',
  za: 'b.title COLLATE NOCASE DESC, b.id DESC',
};

function normalizeTag(value) {
  return String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function isoNow() {
  return new Date().toISOString();
}

export function createStore(filename) {
  const db = new DatabaseSync(filename);
  db.exec('PRAGMA foreign_keys = ON; PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS bookmarks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      url TEXT NOT NULL,
      canonical_url TEXT NOT NULL UNIQUE,
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      description TEXT NOT NULL DEFAULT '',
      source_host TEXT NOT NULL DEFAULT '',
      site_name TEXT NOT NULL DEFAULT '',
      author TEXT NOT NULL DEFAULT '',
      published_at TEXT,
      preview_image TEXT NOT NULL DEFAULT '',
      content_html TEXT NOT NULL DEFAULT '',
      capture_status TEXT NOT NULL CHECK(capture_status IN ('captured', 'none')),
      captured_at TEXT,
      read_later INTEGER NOT NULL DEFAULT 0 CHECK(read_later IN (0,1)),
      archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS tags (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE COLLATE NOCASE
    );
    CREATE TABLE IF NOT EXISTS bookmark_tags (
      bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
      tag_id INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
      PRIMARY KEY (bookmark_id, tag_id)
    );
    CREATE TABLE IF NOT EXISTS saved_views (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK(length(trim(name)) > 0),
      query TEXT NOT NULL DEFAULT '',
      tag TEXT NOT NULL DEFAULT '',
      sort TEXT NOT NULL DEFAULT 'newest',
      created_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_bookmarks_created ON bookmarks(created_at);
    CREATE INDEX IF NOT EXISTS idx_bookmarks_section ON bookmarks(archived, read_later);
    CREATE INDEX IF NOT EXISTS idx_bookmark_tags_tag ON bookmark_tags(tag_id, bookmark_id);
  `);

  const getTagsForIds = (ids) => {
    if (!ids.length) return new Map();
    const placeholders = ids.map(() => '?').join(',');
    const rows = db.prepare(`
      SELECT bt.bookmark_id, t.name
      FROM bookmark_tags bt JOIN tags t ON t.id = bt.tag_id
      WHERE bt.bookmark_id IN (${placeholders})
      ORDER BY t.name COLLATE NOCASE
    `).all(...ids);
    const result = new Map(ids.map((id) => [id, []]));
    for (const row of rows) result.get(row.bookmark_id)?.push(row.name);
    return result;
  };

  const hydrate = (rows) => {
    const tags = getTagsForIds(rows.map((row) => row.id));
    return rows.map((row) => ({
      ...row,
      read_later: Boolean(row.read_later),
      archived: Boolean(row.archived),
      tags: tags.get(row.id) ?? [],
    }));
  };

  const getBookmark = (id) => {
    const row = db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id);
    return row ? hydrate([row])[0] : null;
  };

  const transaction = (work) => {
    db.exec('BEGIN IMMEDIATE');
    try {
      const result = work();
      db.exec('COMMIT');
      return result;
    } catch (error) {
      db.exec('ROLLBACK');
      throw error;
    }
  };

  return {
    db,
    close() { db.close(); },

    findByCanonical(canonicalUrl) {
      const row = db.prepare('SELECT * FROM bookmarks WHERE canonical_url = ?').get(canonicalUrl);
      return row ? hydrate([row])[0] : null;
    },

    getBookmark,

    insertBookmark(bookmark) {
      const now = bookmark.created_at ?? isoNow();
      const result = db.prepare(`
        INSERT INTO bookmarks (
          url, canonical_url, title, description, source_host, site_name, author,
          published_at, preview_image, content_html, capture_status, captured_at,
          read_later, archived, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, ?, ?)
      `).run(
        bookmark.url, bookmark.canonical_url, bookmark.title.trim(), bookmark.description ?? '',
        bookmark.source_host ?? '', bookmark.site_name ?? '', bookmark.author ?? '',
        bookmark.published_at ?? null, bookmark.preview_image ?? '', bookmark.content_html ?? '',
        bookmark.capture_status, bookmark.captured_at ?? null, now, now,
      );
      return getBookmark(Number(result.lastInsertRowid));
    },

    listBookmarks({ section = 'all', query = '', tag = '', sort = 'newest', page = 1, perPage = 8 } = {}) {
      const where = [];
      const values = [];
      if (section === 'archive') where.push('b.archived = 1');
      else if (section === 'later') where.push('b.archived = 0 AND b.read_later = 1');
      else where.push('b.archived = 0');
      if (query.trim()) {
        where.push("instr(lower(b.title || ' ' || b.description || ' ' || b.source_host || ' ' || b.site_name), lower(?)) > 0");
        values.push(query.trim());
      }
      if (tag.trim()) {
        where.push('EXISTS (SELECT 1 FROM bookmark_tags bt JOIN tags t ON t.id = bt.tag_id WHERE bt.bookmark_id = b.id AND t.name = ? COLLATE NOCASE)');
        values.push(normalizeTag(tag));
      }
      const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';
      const total = Number(db.prepare(`SELECT count(*) AS count FROM bookmarks b ${whereSql}`).get(...values).count);
      const safePage = Math.max(1, Number(page) || 1);
      const safePerPage = Math.max(1, Math.min(100, Number(perPage) || 8));
      const totalPages = Math.max(1, Math.ceil(total / safePerPage));
      const actualPage = Math.min(safePage, totalPages);
      const rows = db.prepare(`
        SELECT b.* FROM bookmarks b ${whereSql}
        ORDER BY ${SORT_SQL[sort] ?? SORT_SQL.newest}
        LIMIT ? OFFSET ?
      `).all(...values, safePerPage, (actualPage - 1) * safePerPage);
      const items = hydrate(rows).map(({ content_html, ...bookmark }) => bookmark);
      return { items, total, page: actualPage, perPage: safePerPage, totalPages };
    },

    getNavigation() {
      const counts = db.prepare(`
        SELECT
          sum(CASE WHEN archived = 0 THEN 1 ELSE 0 END) AS all_count,
          sum(CASE WHEN archived = 0 AND read_later = 1 THEN 1 ELSE 0 END) AS later_count,
          sum(CASE WHEN archived = 1 THEN 1 ELSE 0 END) AS archive_count
        FROM bookmarks
      `).get();
      const tags = db.prepare(`
        SELECT t.name, count(*) AS count
        FROM tags t
        JOIN bookmark_tags bt ON bt.tag_id = t.id
        JOIN bookmarks b ON b.id = bt.bookmark_id
        WHERE b.archived = 0
        GROUP BY t.id, t.name
        ORDER BY t.name COLLATE NOCASE
      `).all();
      const savedViews = db.prepare('SELECT * FROM saved_views ORDER BY created_at ASC, id ASC').all();
      return {
        counts: {
          all: Number(counts.all_count ?? 0),
          later: Number(counts.later_count ?? 0),
          archive: Number(counts.archive_count ?? 0),
        },
        tags: tags.map((row) => ({ ...row, count: Number(row.count) })),
        savedViews,
      };
    },

    updateDetails(id, { title, description }) {
      if (!String(title ?? '').trim()) {
        const error = new Error('Add a title so you can recognize this bookmark.');
        error.code = 'title_required'; error.status = 400; throw error;
      }
      const result = db.prepare('UPDATE bookmarks SET title = ?, description = ?, updated_at = ? WHERE id = ?')
        .run(String(title).trim(), String(description ?? '').trim(), isoNow(), id);
      return result.changes ? getBookmark(id) : null;
    },

    setTags(id, tagNames) {
      if (!getBookmark(id)) return null;
      const names = [...new Set((tagNames ?? []).map(normalizeTag).filter(Boolean))];
      transaction(() => {
        db.prepare('DELETE FROM bookmark_tags WHERE bookmark_id = ?').run(id);
        for (const name of names) {
          db.prepare('INSERT INTO tags(name) VALUES (?) ON CONFLICT(name) DO NOTHING').run(name);
          const tag = db.prepare('SELECT id FROM tags WHERE name = ? COLLATE NOCASE').get(name);
          db.prepare('INSERT INTO bookmark_tags(bookmark_id, tag_id) VALUES (?, ?)').run(id, tag.id);
        }
        db.exec('DELETE FROM tags WHERE NOT EXISTS (SELECT 1 FROM bookmark_tags bt WHERE bt.tag_id = tags.id)');
        db.prepare('UPDATE bookmarks SET updated_at = ? WHERE id = ?').run(isoNow(), id);
      });
      return getBookmark(id);
    },

    suggestTags(query, exclude = []) {
      const exclusions = new Set(exclude.map(normalizeTag));
      return this.getNavigation().tags
        .filter((tag) => tag.name.includes(normalizeTag(query)) && !exclusions.has(tag.name))
        .slice(0, 8);
    },

    setReadLater(id, value) {
      const current = getBookmark(id);
      if (!current) return null;
      if (current.archived && value) {
        const error = new Error('Restore the bookmark before adding it to Read later.');
        error.code = 'archived_bookmark'; error.status = 409; throw error;
      }
      db.prepare('UPDATE bookmarks SET read_later = ?, updated_at = ? WHERE id = ?').run(value ? 1 : 0, isoNow(), id);
      return getBookmark(id);
    },

    archive(id) {
      const result = db.prepare('UPDATE bookmarks SET archived = 1, read_later = 0, updated_at = ? WHERE id = ?').run(isoNow(), id);
      return result.changes ? getBookmark(id) : null;
    },

    restore(id) {
      const result = db.prepare('UPDATE bookmarks SET archived = 0, read_later = 0, updated_at = ? WHERE id = ?').run(isoNow(), id);
      return result.changes ? getBookmark(id) : null;
    },

    deleteBookmark(id) {
      return transaction(() => {
        const existing = getBookmark(id);
        if (!existing) return null;
        db.prepare('DELETE FROM bookmarks WHERE id = ?').run(id);
        db.exec('DELETE FROM tags WHERE NOT EXISTS (SELECT 1 FROM bookmark_tags bt WHERE bt.tag_id = tags.id)');
        return existing;
      });
    },

    createSavedView({ name, query = '', tag = '', sort = 'newest' }) {
      if (!String(name ?? '').trim()) {
        const error = new Error('Give this saved view a name.');
        error.code = 'name_required'; error.status = 400; throw error;
      }
      const result = db.prepare('INSERT INTO saved_views(name, query, tag, sort, created_at) VALUES (?, ?, ?, ?, ?)')
        .run(String(name).trim(), String(query), normalizeTag(tag), SORT_SQL[sort] ? sort : 'newest', isoNow());
import { canonicalizeUrl, displayHost, parseWebUrl } from './url.js';
import { CaptureError, capturePage, checkPageAvailability } from './capture.js';

export class DuplicateError extends Error {
  constructor(bookmark) {
    super('You already saved this page.');
    this.name = 'DuplicateError';
    this.code = 'duplicate';
    this.status = 409;
    this.bookmark = bookmark;
  }
}

export function createService(store, { allowPrivateFetch = false } = {}) {
  return {
    async saveUrl(url) {
      const inputCanonical = canonicalizeUrl(url);
      const inputDuplicate = store.findByCanonical(inputCanonical);
      if (inputDuplicate) throw new DuplicateError(inputDuplicate);
      let captured;
      try {
        captured = await capturePage(url, { allowPrivate: allowPrivateFetch });
      } catch (error) {
        if (error instanceof CaptureError) {
          error.url = parseWebUrl(url).toString();
        }
        throw error;
      }
      const finalCanonical = canonicalizeUrl(captured.finalUrl);
      const redirectDuplicate = store.findByCanonical(finalCanonical);
      if (redirectDuplicate) throw new DuplicateError(redirectDuplicate);
      return store.insertBookmark({
        url: captured.finalUrl,
        canonical_url: finalCanonical,
        title: captured.title,
        description: captured.description,
        source_host: captured.sourceHost,
        site_name: captured.siteName,
        author: captured.author,
        published_at: captured.publishedAt,
        preview_image: captured.previewImage,
        content_html: captured.contentHtml,
        capture_status: 'captured',
        captured_at: captured.capturedAt,
      });
    },

    saveManual({ url, title, description = '' }) {
      const canonical = canonicalizeUrl(url);
      const duplicate = store.findByCanonical(canonical);
      if (duplicate) throw new DuplicateError(duplicate);
      if (!String(title ?? '').trim()) {
        const error = new Error('Add a title so you can recognize this bookmark.');
        error.code = 'title_required'; error.status = 400; throw error;
      }
      const parsed = parseWebUrl(url);
      return store.insertBookmark({
        url: parsed.toString(),
        canonical_url: canonical,
        title: String(title).trim(),
        description: String(description).trim(),
        source_host: displayHost(url),
        site_name: displayHost(url),
        author: '',
        preview_image: '',
        content_html: '',
        capture_status: 'none',
        captured_at: null,
      });
    },

    async availability(id) {
      const bookmark = store.getBookmark(id);
      if (!bookmark) return null;
      if (bookmark.capture_status !== 'captured') return { available: false, reason: 'No saved page copy.' };
      return checkPageAvailability(bookmark.url, { allowPrivate: allowPrivateFetch });
    },
  };
}
import dns from 'node:dns/promises';
import net from 'node:net';
import { load } from 'cheerio';
import sanitizeHtml from 'sanitize-html';
import { displayHost, parseWebUrl } from './url.js';

const MAX_HTML_BYTES = 5 * 1024 * 1024;
const MAX_IMAGE_BYTES = 2 * 1024 * 1024;
const MAX_EMBEDDED_IMAGES = 8;
const REDIRECT_LIMIT = 5;

export class CaptureError extends Error {
  constructor(message = 'We could not read this page.') {
    super(message);
    this.name = 'CaptureError';
    this.code = 'capture_failed';
    this.status = 422;
  }
}

function isPrivateIp(address) {
  if (net.isIPv4(address)) {
    const [a, b] = address.split('.').map(Number);
    return a === 10 || a === 127 || a === 0 || (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) ||
      (a === 100 && b >= 64 && b <= 127) || a >= 224;
  }
  if (net.isIPv6(address)) {
    const normalized = address.toLowerCase();
    return normalized === '::1' || normalized === '::' || normalized.startsWith('fc') ||
      normalized.startsWith('fd') || normalized.startsWith('fe8') || normalized.startsWith('fe9') ||
      normalized.startsWith('fea') || normalized.startsWith('feb');
  }
  return true;
}

async function assertPublicDestination(value, allowPrivate) {
  const url = parseWebUrl(value);
  if (allowPrivate) return url;
  if (url.hostname.toLowerCase() === 'localhost') throw new CaptureError('Private network addresses cannot be captured.');
  const directIp = net.isIP(url.hostname);
  const addresses = directIp ? [{ address: url.hostname }] : await dns.lookup(url.hostname, { all: true });
  if (!addresses.length || addresses.some(({ address }) => isPrivateIp(address))) {
    throw new CaptureError('Private network addresses cannot be captured.');
  }
  return url;
}

async function readLimited(response, maximum) {
  const announced = Number(response.headers.get('content-length') || 0);
  if (announced > maximum) throw new CaptureError('This page is too large to capture safely.');
  if (!response.body) return Buffer.alloc(0);
  const reader = response.body.getReader();
  const chunks = [];
  let size = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > maximum) {
      await reader.cancel();
      throw new CaptureError('This page is too large to capture safely.');
    }
    chunks.push(Buffer.from(value));
  }
  return Buffer.concat(chunks);
}

async function safeFetch(value, { allowPrivate = false, method = 'GET', maximum = MAX_HTML_BYTES } = {}) {
  let current = (await assertPublicDestination(value, allowPrivate)).toString();
  for (let redirects = 0; redirects <= REDIRECT_LIMIT; redirects += 1) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 12_000);
    let response;
    try {
      response = await fetch(current, {
        method,
        redirect: 'manual',
        signal: controller.signal,
        headers: {
          'user-agent': 'Keepwell/1.0 personal bookmark archiver',
          accept: method === 'HEAD' ? '*/*' : 'text/html,application/xhtml+xml;q=0.9,*/*;q=0.2',
        },
      });
    } catch (error) {
      clearTimeout(timeout);
      throw new CaptureError(error.name === 'AbortError' ? 'The page took too long to respond.' : 'The page could not be reached.');
    }
    clearTimeout(timeout);
    if ([301, 302, 303, 307, 308].includes(response.status)) {
      const location = response.headers.get('location');
      if (!location || redirects === REDIRECT_LIMIT) throw new CaptureError('The page redirected too many times.');
      current = new URL(location, current).toString();
      await assertPublicDestination(current, allowPrivate);
      continue;
    }
    if (!response.ok) throw new CaptureError(`The page returned ${response.status}.`);
    const body = method === 'HEAD' ? Buffer.alloc(0) : await readLimited(response, maximum);
    return { response, body, finalUrl: current };
  }
  throw new CaptureError('The page redirected too many times.');
}

function firstContent($, selectors) {
  for (const selector of selectors) {
    const element = $(selector).first();
    const value = element.attr('content') ?? element.text();
    if (value?.trim()) return value.trim();
  }
  return '';
}

function absoluteUrl(value, base) {
  if (!value) return '';
  try { return new URL(value, base).toString(); } catch { return ''; }
}

async function fetchImageAsDataUrl(value, options) {
  if (!value) return '';
  try {
    const { response, body } = await safeFetch(value, { ...options, maximum: MAX_IMAGE_BYTES });
    const type = response.headers.get('content-type')?.split(';')[0]?.trim().toLowerCase() ?? '';
    if (!type.startsWith('image/') || type === 'image/svg+xml') return '';
    return `data:${type};base64,${body.toString('base64')}`;
  } catch {
    return '';
  }
}

async function embedArticleImages(html, baseUrl, options) {
  const $ = load(`<main id="capture-root">${html}</main>`);
  const images = $('#capture-root img').slice(0, MAX_EMBEDDED_IMAGES).toArray();
  for (const image of images) {
    const element = $(image);
    const source = absoluteUrl(element.attr('src') || element.attr('data-src'), baseUrl);
    const embedded = await fetchImageAsDataUrl(source, options);
    if (embedded) element.attr('src', embedded);
    else element.remove();
    element.removeAttr('srcset sizes loading data-src');
  }
  $('#capture-root img').slice(MAX_EMBEDDED_IMAGES).remove();
  return $('#capture-root').html() ?? '';
}

export async function capturePage(value, { allowPrivate = false } = {}) {
  const { response, body, finalUrl } = await safeFetch(value, { allowPrivate });
  const contentType = response.headers.get('content-type')?.toLowerCase() ?? '';
  if (!contentType.includes('text/html') && !contentType.includes('application/xhtml+xml')) {
    throw new CaptureError('This address did not return a readable webpage.');
  }
  const markup = body.toString('utf8');
  const $ = load(markup);
  const title = firstContent($, ['meta[property="og:title"]', 'meta[name="twitter:title"]', 'title', 'h1']);
  if (!title) throw new CaptureError('The page did not provide a recognizable title.');
  const description = firstContent($, [
    'meta[property="og:description"]', 'meta[name="description"]', 'meta[name="twitter:description"]',
    'article p', 'main p', 'p',
  ]).slice(0, 1000);
  const siteName = firstContent($, ['meta[property="og:site_name"]']) || displayHost(finalUrl);
  const author = firstContent($, ['meta[name="author"]', '[rel="author"]', '.byline', '[class*="author"]']).slice(0, 300);
  const publishedAt = firstContent($, [
    'meta[property="article:published_time"]', 'meta[name="date"]', 'time[datetime]',
  ]).slice(0, 100);
  const imageUrl = absoluteUrl(firstContent($, [
    'meta[property="og:image"]', 'meta[name="twitter:image"]', 'article img', 'main img', 'img',
  ]), finalUrl);

  $('script,style,noscript,iframe,object,embed,form,button,input,textarea,select,nav,aside,[aria-hidden="true"]').remove();
  $('[style]').removeAttr('style');
  const candidate = $('article').first().length ? $('article').first() : $('main').first().length ? $('main').first() : $('body');
  candidate.find('a[href]').each((_, element) => {
    const href = absoluteUrl($(element).attr('href'), finalUrl);
    if (href) $(element).attr({ href, target: '_blank', rel: 'noreferrer noopener' });
    else $(element).removeAttr('href');
  });
  candidate.find('img').each((_, element) => {
    const source = absoluteUrl($(element).attr('src') || $(element).attr('data-src'), finalUrl);
    if (source) $(element).attr('src', source);
  });
  const sanitized = sanitizeHtml(candidate.html() ?? '', {
    allowedTags: ['p','h1','h2','h3','h4','h5','h6','blockquote','pre','code','ul','ol','li','strong','em','b','i','u','s','a','img','figure','figcaption','table','thead','tbody','tr','th','td','hr','br','div','section','span'],
    allowedAttributes: { a: ['href','target','rel'], img: ['src','alt','title'], '*': ['lang'] },
    allowedSchemes: ['http', 'https', 'data'],
    allowedSchemesByTag: { img: ['http', 'https', 'data'] },
    transformTags: { div: 'section' },
  });
  const contentHtml = await embedArticleImages(sanitized, finalUrl, { allowPrivate });
  const previewImage = await fetchImageAsDataUrl(imageUrl, { allowPrivate });

  return {
    finalUrl,
    title: title.slice(0, 500),
    description,
    sourceHost: displayHost(finalUrl),
    siteName: siteName.slice(0, 300),
    author,
    publishedAt: publishedAt || null,
    previewImage,
    contentHtml,
    capturedAt: new Date().toISOString(),
  };
}

export async function checkPageAvailability(value, { allowPrivate = false } = {}) {
  try {
    await safeFetch(value, { allowPrivate, method: 'HEAD', maximum: 0 });
    return { available: true };
  } catch (error) {
    return { available: false, reason: error.message };
  }
}
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import express from 'express';
import { createStore } from './store.js';
import { createService } from './service.js';

const sourceDirectory = path.dirname(fileURLToPath(import.meta.url));
const implementationDirectory = path.resolve(sourceDirectory, '..');
const publicDirectory = path.join(implementationDirectory, 'public');

function numericId(value) {
  const id = Number.parseInt(value, 10);
  if (!Number.isInteger(id) || id < 1) {
    const error = new Error('Bookmark not found.');
    error.code = 'not_found'; error.status = 404; throw error;
  }
  return id;
}

function requireBookmark(value) {
  if (!value) {
    const error = new Error('Bookmark not found.');
    error.code = 'not_found'; error.status = 404; throw error;
  }
  return value;
}

export function createApplication({ databasePath, allowPrivateFetch = false, testMode = false } = {}) {
  const resolvedDatabase = path.resolve(databasePath ?? path.join(implementationDirectory, 'data', 'keepwell.sqlite'));
  fs.mkdirSync(path.dirname(resolvedDatabase), { recursive: true });
  const store = createStore(resolvedDatabase);
  const service = createService(store, { allowPrivateFetch });
  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '1mb' }));
  app.use((request, response, next) => {
    response.setHeader('Content-Security-Policy', "default-src 'self'; img-src 'self' data: https:; style-src 'self'; script-src 'self'; connect-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'");
    response.setHeader('X-Content-Type-Options', 'nosniff');
    response.setHeader('Referrer-Policy', 'no-referrer');
    next();
  });

  app.get('/api/health', (_request, response) => response.json({ ok: true }));

  app.get('/api/state', (request, response) => {
    const list = store.listBookmarks({
      section: request.query.section,
      query: request.query.q,
      tag: request.query.tag,
      sort: request.query.sort,
      page: request.query.page,
      perPage: 8,
    });
    response.json({ ...list, navigation: store.getNavigation() });
  });

  app.get('/api/bookmarks/:id', (request, response) => {
    response.json(requireBookmark(store.getBookmark(numericId(request.params.id))));
  });

  app.post('/api/bookmarks', async (request, response, next) => {
    try {
      const bookmark = await service.saveUrl(request.body?.url);
      response.status(201).json(bookmark);
    } catch (error) { next(error); }
  });

  app.post('/api/bookmarks/manual', (request, response, next) => {
    try {
      response.status(201).json(service.saveManual(request.body ?? {}));
    } catch (error) { next(error); }
  });

  app.patch('/api/bookmarks/:id', (request, response, next) => {
    try {
      response.json(requireBookmark(store.updateDetails(numericId(request.params.id), request.body ?? {})));
    } catch (error) { next(error); }
  });

  app.put('/api/bookmarks/:id/tags', (request, response, next) => {
    try {
      response.json(requireBookmark(store.setTags(numericId(request.params.id), request.body?.tags)));
    } catch (error) { next(error); }
  });

  app.get('/api/tags/suggest', (request, response) => {
    const exclude = String(request.query.exclude ?? '').split(',').filter(Boolean);
    response.json(store.suggestTags(String(request.query.q ?? ''), exclude));
  });

  app.patch('/api/bookmarks/:id/read-later', (request, response, next) => {
    try {
      response.json(requireBookmark(store.setReadLater(numericId(request.params.id), Boolean(request.body?.value))));
    } catch (error) { next(error); }
  });

  app.post('/api/bookmarks/:id/archive', (request, response, next) => {
    try { response.json(requireBookmark(store.archive(numericId(request.params.id)))); }
    catch (error) { next(error); }
  });

  app.post('/api/bookmarks/:id/restore', (request, response, next) => {
    try { response.json(requireBookmark(store.restore(numericId(request.params.id)))); }
    catch (error) { next(error); }
  });

  app.delete('/api/bookmarks/:id', (request, response, next) => {
    try { response.json(requireBookmark(store.deleteBookmark(numericId(request.params.id)))); }
    catch (error) { next(error); }
  });

  app.get('/api/bookmarks/:id/availability', async (request, response, next) => {
    try { response.json(requireBookmark(await service.availability(numericId(request.params.id)))); }
    catch (error) { next(error); }
  });

  app.post('/api/views', (request, response, next) => {
    try { response.status(201).json(store.createSavedView(request.body ?? {})); }
    catch (error) { next(error); }
  });

  if (testMode) {
    app.post('/api/__test/reset', (_request, response) => {
      store.clearAll();
      response.json({ ok: true });
    });
    app.post('/api/__test/seed', (request, response, next) => {
      try {
        const rows = Array.isArray(request.body?.bookmarks) ? request.body.bookmarks : [];
        const inserted = rows.map((bookmark) => store.insertBookmark({
          url: bookmark.url,
          canonical_url: bookmark.canonical_url,
          title: bookmark.title,
          description: bookmark.description ?? '',
          source_host: bookmark.source_host ?? '',
          site_name: bookmark.site_name ?? '',
          author: bookmark.author ?? '',
          published_at: bookmark.published_at ?? null,
          preview_image: bookmark.preview_image ?? '',
          content_html: bookmark.content_html ?? '',
          capture_status: bookmark.capture_status ?? 'captured',
          captured_at: bookmark.captured_at ?? new Date().toISOString(),
          created_at: bookmark.created_at,
        }));
        for (let index = 0; index < inserted.length; index += 1) {
          if (rows[index].tags) store.setTags(inserted[index].id, rows[index].tags);
          if (rows[index].read_later) store.setReadLater(inserted[index].id, true);
          if (rows[index].archived) store.archive(inserted[index].id);
        }
        response.status(201).json({ bookmarks: inserted.map((row) => store.getBookmark(row.id)) });
      } catch (error) { next(error); }
    });
  }

  app.use(express.static(publicDirectory, { extensions: ['html'], maxAge: 0 }));
  app.use((request, response, next) => {
    if (request.method !== 'GET' || request.path.startsWith('/api/')) return next();
    response.sendFile(path.join(publicDirectory, 'index.html'));
  });

  app.use((error, _request, response, _next) => {
    const status = Number(error.status) || 500;
    const payload = {
      error: {
        code: error.code ?? 'internal_error',
        message: status >= 500 ? 'Something went wrong.' : error.message,
      },
    };
    if (error.bookmark) payload.error.bookmark = error.bookmark;
    if (error.url) payload.error.url = error.url;
    if (status >= 500) console.error(error);
    response.status(status).json(payload);
  });

  return { app, store };
}

export function startServer(options = {}) {
  const port = Number(options.port ?? process.env.PORT ?? 4000);
  const host = options.host ?? process.env.HOST ?? '0.0.0.0';
  const databasePath = options.databasePath ?? process.env.KEEPWELL_DB;
  const testMode = options.testMode ?? process.env.KEEPWELL_TEST_MODE === '1';
  const allowPrivateFetch = options.allowPrivateFetch ?? process.env.KEEPWELL_ALLOW_PRIVATE_FETCH === '1';
  const { app, store } = createApplication({ databasePath, testMode, allowPrivateFetch });
  const server = app.listen(port, host, () => console.log(`Keepwell listening on http://${host}:${port}`));
  const close = () => server.close(() => store.close());
  process.once('SIGTERM', close);
  process.once('SIGINT', close);
  return { server, store };
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  startServer();
}

