.nav-link, .side-list button { display: grid; width: 100%; grid-template-columns: 23px 1fr auto; align-items: center; gap: 7px; padding: 11px 12px; border: 0; border-radius: 8px; color: #c4ced8; background: transparent; font-size: 13px; font-weight: 650; text-align: left; }
