.nav-link.is-active, .side-list button.is-active { color: #fff; background: rgba(255,255,255,.12); }
.nav-symbol { color: #aebdcb; font-size: 15px; }.nav-link strong { font-size: 10px; font-weight: 650; opacity: .75; }
.side-section { margin: 27px 6px 0; padding-top: 20px; border-top: 1px solid rgba(255,255,255,.12); }.side-section h2 { margin: 0 8px 9px; color: #8191a2; font-size: 9px; letter-spacing: .14em; text-transform: uppercase; }.side-list button { grid-template-columns: 16px 1fr auto; padding: 7px 8px; font-size: 11px; }.side-list button strong { color: #8fa0b1; font-size: 9px; }.side-bullet { width: 7px; height: 7px; border-radius: 50%; background: #d2a657; }.saved-symbol { color: #d7ac5c; font-size: 12px; }
.sidebar-note { display: flex; align-items: flex-start; gap: 9px; margin-top: auto; padding: 17px 10px 0; border-top: 1px solid rgba(255,255,255,.12); }.sidebar-note p { margin: 0; color: #9fadb9; font-size: 10px; line-height: 1.55; }.sidebar-note strong { color: #e4e9ed; font-size: 11px; }.status-dot { width: 7px; height: 7px; margin-top: 4px; flex: 0 0 auto; border-radius: 50%; background: #7fc19c; box-shadow: 0 0 0 3px rgba(127,193,156,.13); }

.main-content, .reader-screen { grid-column: 2; width: min(1040px, calc(100vw - 310px)); margin: 0 auto; padding: 43px 0 70px; }
.page-header { display: flex; align-items: end; justify-content: space-between; margin-bottom: 27px; }.kicker { margin: 0 0 7px; color: #7b868a; font-size: 9px; font-weight: 800; letter-spacing: .17em; }.page-header h1 { margin: 0; font-family: Georgia, serif; font-size: 34px; letter-spacing: -.025em; }.page-subtitle { margin: 0 0 5px; color: #7a8589; font-size: 12px; }
.save-box { padding: 22px; border: 1px solid var(--line); border-radius: 14px; background: var(--surface); box-shadow: var(--shadow); }.save-heading-row { display: flex; align-items: start; justify-content: space-between; margin-bottom: 16px; }.save-heading-row h2 { margin: 0 0 4px; font-family: Georgia,serif; font-size: 20px; }.save-heading-row p { margin: 0; color: var(--muted); font-size: 12px; }.capture-label { padding: 5px 8px; border-radius: 99px; color: #486776; background: var(--blue-soft); font-size: 9px; font-weight: 750; }
.save-control { position: relative; display: flex; }.input-symbol { position: absolute; left: 15px; top: 13px; color: #718086; font-size: 17px; }.save-control input { width: 100%; height: 48px; padding: 0 165px 0 43px; border: 1px solid #c6cecf; border-radius: 9px; color: var(--ink); background: #fcfdfa; }.save-control .primary-button { position: absolute; top: 4px; right: 4px; height: 40px; }.primary-button, .danger-button { padding: 0 16px; border: 1px solid var(--navy); border-radius: 7px; color: #fff; background: var(--navy); font-size: 11px; font-weight: 750; }.primary-button:disabled { opacity: .65; cursor: wait; }
.inline-error { margin: 7px 2px 0; color: var(--danger); font-size: 10px; font-weight: 650; }.invalid { border-color: var(--danger) !important; box-shadow: 0 0 0 3px rgba(159,68,60,.1) !important; }
.save-message { display: grid; grid-template-columns: 32px 1fr auto; align-items: center; gap: 10px; margin-top: 14px; padding: 12px 13px; border: 1px solid #d5ba86; border-radius: 9px; background: #fff7e6; }.message-icon { display: grid; width: 28px; height: 28px; place-items: center; border-radius: 50%; color: #fff; background: #a87438; font-size: 13px; font-weight: 800; }.save-message strong { font-size: 11px; }.save-message p { margin: 2px 0; color: #75684e; font-size: 10px; }.save-message small { color: #9a8c71; font-size: 9px; }.message-actions { display: flex; gap: 5px; }.save-message button { padding: 7px 9px; border: 1px solid #c9ad78; border-radius: 6px; color: #6b5227; background: #fff; font-size: 9px; font-weight: 750; }.message-actions button:last-child { color: #fff; background: #725525; }.duplicate-message { border-color: #a8bdca; background: #edf5f8; }.duplicate-message .message-icon { background: #557d92; }.duplicate-message p { color: #607681; }

