adding: 7px; border: 1px solid var(--line); }.reader-footer { display: flex; justify-content: space-between; padding: 16px 30px; color: #7a8588; background: #f1f2ee; font-size: 9px; }.reader-footer a { color: var(--blue); font-weight: 750; text-decoration: none; }

dialog { padding: 0; border: 0; color: var(--ink); background: var(--surface); box-shadow: 0 25px 70px rgba(17,28,37,.24); }dialog::backdrop { background: rgba(18,28,37,.38); backdrop-filter: blur(2px); }.drawer-dialog { width: 430px; max-width: none; height: 100vh; max-height: none; margin: 0 0 0 auto; border-radius: 0; }.drawer-form { display: flex; height: 100%; flex-direction: column; padding: 29px; }.drawer-form header { display: flex; align-items: start; justify-content: space-between; padding-bottom: 18px; border-bottom: 1px solid var(--line); }.drawer-form h2, .modal-dialog h2 { margin: 0; font-family: Georgia,serif; font-size: 26px; }.icon-button { padding: 0; border: 0; color: #6b777c; background: none; font-size: 27px; }.drawer-context { margin: 19px 0 23px; color: #647176; font-size: 11px; line-height: 1.45; }.drawer-form label, .modal-dialog label { margin: 0 0 6px; color: #536168; font-size: 9px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }.drawer-form label:not(:first-of-type) { margin-top: 18px; }.drawer-form label span { color: #8b9496; font-weight: 600; text-transform: none; }.drawer-form input, .drawer-form textarea, .modal-dialog input { width: 100%; padding: 10px 11px; border: 1px solid #bcc7c8; border-radius: 8px; color: var(--ink); background: #fff; resize: vertical; }.drawer-form footer, .modal-dialog footer { display: flex; justify-content: flex-end; gap: 7px; margin-top: auto; padding-top: 18px; border-top: 1px solid var(--line); }.drawer-form footer .primary-button, .modal-dialog footer .primary-button { min-height: 36px; }.drawer-warning { margin-bottom: 21px; padding: 11px; border-radius: 8px; color: #73572e; background: #fff4de; font-size: 10px; line-height: 1.5; }.selected-tags { display: flex; min-height: 34px; flex-wrap: wrap; gap: 6px; }.selected-tags button { padding: 6px 8px 6px 10px; border: 0; border-radius: 99px; color: #355b6d; background: var(--blue-soft); font-size: 10px; font-weight: 700; }.selected-tags button span { margin-left: 4px; }.tag-entry-row { display: flex; gap: 6px; }.tag-entry-row input { flex: 1; }.tag-suggestions { overflow: hidden; margin-top: 6px; border: 1px solid #cfd7d7; border-radius: 8px; background: #fff; box-shadow: 0 8px 20px rgba(26,39,48,.1); }.tag-suggestions button { display: flex; width: 100%; justify-content: space-between; padding: 9px 10px; border: 0; border-bottom: 1px solid #eceeed; color: #42535a; background: #fff; font-size: 10px; }.tag-suggestions button:last-child { border-bottom: 0; }.tag-suggestions button small { color: #879194; }.field-help { margin-top: 7px; color: #858f92; font-size: 9px; }
.modal-dialog { width: 410px; border-radius: 13px; }.modal-dialog form { position: relative; padding: 28px; }.modal-x { position: absolute; top: 17px; right: 20px; }.modal-copy { margin: 8px 0 20px; color: #6d787c; font-size: 11px; line-height: 1.5; }.modal-dialog footer { margin-top: 21px; }.view-summary { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 11px; }.view-summary span { padding: 5px 7px; border-radius: 99px; color: #49606a; background: #e9eef0; font-size: 8px; font-weight: 700; }.danger-dialog form { display: grid; justify-items: center; text-align: center; }.danger-symbol { display: grid; width: 46px; height: 46px; margin-bottom: 15px; place-items: center; border-radius: 50%; color: var(--danger); background: var(--danger-soft); font-family: Georgia,serif; font-size: 24px; font-weight: 800; }.danger-dialog p { margin: 10px 0 0; color: #697479; font-size: 11px; line-height: 1.55; }.danger-dialog footer { width: 100%; }.danger-button { min-height: 36px; border-color: var(--danger); background: var(--danger); }
.toast { position: fixed; z-index: 20; right: 24px; bottom: 22px; display: flex; align-items: center; gap: 8px; max-width: 360px; padding: 12px 15px; border-radius: 8px; color: #fff; background: var(--navy); box-shadow: 0 12px 30px rgba(20,30,38,.23); animation: toast-in .25s ease-out; }.toast > span { display: grid; width: 18px; height: 18px; place-items: center; border-radius: 50%; color: var(--navy); background: #dce7ed; font-size: 10px; font-weight: 800; }.toast p { margin: 0; font-size: 10px; }
